"use client"

/** Clean-room scope checklist. Rows stagger in; effort is a donut of included hours. */

import * as React from "react"
import { ChevronDown, Minus } from "lucide-react"
import { motion, useReducedMotion } from "motion/react"

import { Checkbox } from "@/components/ui/checkbox"
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible"
import { cn } from "@/lib/utils"
import {
  formatHours,
  phaseShares,
  scopeHours,
  type ScopeOrigin,
  type ScopePhase,
} from "@/lib/proposal"
import { DonutChart } from "@/components/ui/donut-chart"

export type ProposalScopeProps = {
  phases: readonly ScopePhase[]
  onToggle: (taskId: string) => void
  exclusions: readonly { id: string; label: string }[]
  exclusionsTitle?: string
  effortLabel?: string
  originLabels?: Partial<Record<ScopeOrigin, string>>
  locale?: string
  className?: string
}

const DEFAULT_ORIGIN: Record<ScopeOrigin, string> = {
  adapted: "Adapted",
  edited: "Edited",
  added: "Added from your answer",
}

export function ProposalScope({
  phases,
  onToggle,
  exclusions,
  exclusionsTitle = "Not included",
  effortLabel = "Effort",
  originLabels,
  locale = "en-US",
  className,
}: ProposalScopeProps) {
  const reduced = !!useReducedMotion()
  const labels = { ...DEFAULT_ORIGIN, ...originLabels }
  const shares = phaseShares(phases).filter((share) => share.value > 0)
  const total = scopeHours(phases)
  const delayOf = new Map(
    phases.flatMap((phase) => phase.tasks).map((task, index) => [task.id, reduced ? 0 : Math.min(0.1, 0.05 + index * 0.01)]),
  )

  return (
    <div data-slot="proposal-scope" className={cn("grid min-w-0 gap-4 lg:grid-cols-[minmax(0,1.4fr)_minmax(14rem,0.7fr)]", className)}>
      <div className="grid min-w-0 gap-2">
        {phases.map((phase) => (
          <Collapsible key={phase.id} defaultOpen className="rounded-xl border border-border bg-card">
            <CollapsibleTrigger className="flex w-full items-center justify-between gap-2 px-3 py-2 text-start text-sm font-medium">
              <span className="min-w-0 truncate">{phase.title}</span>
              <ChevronDown className="size-4 shrink-0 text-muted-foreground" />
            </CollapsibleTrigger>
            <CollapsibleContent className="border-t border-border">
              <ul>
                {phase.tasks.map((task) => {
                  const delay = delayOf.get(task.id) ?? 0
                  return (
                    <motion.li
                      key={task.id}
                      initial={reduced ? false : { opacity: 0, y: 8 }}
                      animate={{ opacity: 1, y: 0 }}
                      transition={{ duration: reduced ? 0 : 0.2, delay }}
                      className="flex min-w-0 items-center gap-3 px-3 py-2"
                    >
                      <Checkbox
                        checked={task.included}
                        onCheckedChange={() => onToggle(task.id)}
                        aria-label={task.title}
                        className="rounded-full"
                      />
                      <span className={cn("min-w-0 flex-1 text-sm wrap-break-word", !task.included && "text-muted-foreground line-through")}>
                        {task.title}
                      </span>
                      {task.origin ? (
                        <span className="hidden max-w-36 truncate rounded-full bg-muted px-2 py-0.5 text-[11px] text-muted-foreground sm:inline">
                          {labels[task.origin]}
                        </span>
                      ) : null}
                      <span className="shrink-0 text-xs tabular-nums text-muted-foreground">
                        {formatHours(task.hours, locale)}h
                      </span>
                    </motion.li>
                  )
                })}
              </ul>
            </CollapsibleContent>
          </Collapsible>
        ))}
      </div>
      <div className="grid h-fit gap-4">
        <DonutChart
          data={shares.length ? shares : [{ key: "empty", label: effortLabel, value: 0 }]}
          label={effortLabel}
          totalLabel={formatHours(total, locale)}
          unit="h"
          size={180}
        />
        <section aria-label={exclusionsTitle}>
          <h2 className="text-sm font-medium">{exclusionsTitle}</h2>
          <ul className="mt-2 flex flex-col gap-1">
            {exclusions.map((item) => (
              <li key={item.id} className="flex min-w-0 items-start gap-2 text-sm text-muted-foreground">
                <Minus className="mt-0.5 size-4 shrink-0" />
                <span className="wrap-break-word">{item.label}</span>
              </li>
            ))}
          </ul>
        </section>
      </div>
    </div>
  )
}

/**
 * Proposal workflow helpers. Data in, numbers out. No fetching and no theme.
 * Clean-room behavior: no product names, sample copy, or assets from any demo.
 */

import { moveItem } from "@/lib/reorder"

export const PROPOSAL_TABS = [
  "summary",
  "discovery",
  "scope",
  "similar",
  "estimate",
  "price",
  "risks",
  "proposal",
  "sow",
  "activity",
] as const

export type ProposalTabId = (typeof PROPOSAL_TABS)[number]

export type ProposalActionTone = "risk" | "price" | "low-confidence" | "follow-up"

export type ScopeOrigin = "adapted" | "edited" | "added"

export type ScopeTask = {
  id: string
  title: string
  hours: number
  origin?: ScopeOrigin
  included: boolean
}

export type ScopePhase = {
  id: string
  title: string
  tasks: readonly ScopeTask[]
}

export type ClarifyEffect = {
  id: string
  label: string
  hours: number
}

export type ClarifyOption = {
  value: string
  label: string
  effects: readonly ClarifyEffect[]
}

export type ClarifyQuestion = {
  id: string
  prompt: string
  detail?: string
  options: readonly ClarifyOption[]
}

export type ClarificationImpact = {
  previous: number
  next: number
  delta: number
  reasons: ClarifyEffect[]
  priceLow: number
  priceHigh: number
  weeksLow: number
  weeksHigh: number
}

export type EstimateLine = {
  id: string
  phase: string
  hours: number
  rate: number
  historicalHours: number
}

export type EstimateTotals = {
  hours: number
  amount: number
  historicalHours: number
}

export type PriceLineKind = "base" | "upsell" | "downsell"

export type PriceLine = {
  id: string
  label: string
  amount: number
  kind: PriceLineKind
}

export type ProposalSection = {
  id: string
  title: string
  body: string
}

export type PreflightItem = {
  id: string
  label: string
  done: boolean
}

export function scopeHours(phases: readonly ScopePhase[]): number {
  return phases.reduce(
    (sum, phase) =>
      sum + phase.tasks.reduce((inner, task) => inner + (task.included ? task.hours : 0), 0),
    0,
  )
}

export function phaseShares(phases: readonly ScopePhase[]) {
  return phases.map((phase) => ({
    key: phase.id,
    label: phase.title,
    value: phase.tasks.reduce((sum, task) => sum + (task.included ? task.hours : 0), 0),
  }))
}

export function toggleScopeTask(phases: readonly ScopePhase[], taskId: string): ScopePhase[] {
  return phases.map((phase) => ({
    ...phase,
    tasks: phase.tasks.map((task) =>
      task.id === taskId ? { ...task, included: !task.included } : task,
    ),
  }))
}

export function clarificationImpact({
  baseHours,
  questions,
  answers,
  rate,
  hoursPerWeek,
}: {
  baseHours: number
  questions: readonly ClarifyQuestion[]
  answers: Readonly<Record<string, string>>
  rate: number
  hoursPerWeek: number
}): ClarificationImpact {
  const reasons: ClarifyEffect[] = []
  for (const question of questions) {
    const chosen = answers[question.id]
    const option = question.options.find((item) => item.value === chosen)
    if (option) reasons.push(...option.effects)
  }
  const delta = reasons.reduce((sum, effect) => sum + effect.hours, 0)
  const next = Math.max(0, baseHours + delta)
  const weekly = hoursPerWeek > 0 ? hoursPerWeek : 1
  const safeRate = Number.isFinite(rate) ? rate : 0
  return {
    previous: baseHours,
    next,
    delta,
    reasons,
    priceLow: Math.round(next * safeRate * 0.92),
    priceHigh: Math.round(next * safeRate * 1.12),
    weeksLow: Math.round((next / weekly) * 10) / 10,
    weeksHigh: Math.round(((next / weekly) * 1.3) * 10) / 10,
  }
}

export function estimateAmount(line: EstimateLine): number {
  return line.hours * line.rate
}

export function estimateTotals(lines: readonly EstimateLine[]): EstimateTotals {
  return lines.reduce<EstimateTotals>(
    (totals, line) => ({
      hours: totals.hours + line.hours,
      amount: totals.amount + estimateAmount(line),
      historicalHours: totals.historicalHours + line.historicalHours,
    }),
    { hours: 0, amount: 0, historicalHours: 0 },
  )
}

export function priceTotal(lines: readonly PriceLine[]): number {
  return lines.reduce((sum, line) => sum + line.amount, 0)
}

export function clampPrice(value: number, min: number, max: number): number {
  const low = Math.min(min, max)
  const high = Math.max(min, max)
  if (!Number.isFinite(value)) return low
  return Math.min(high, Math.max(low, value))
}

export function moveSection(sections: readonly ProposalSection[], id: string, direction: -1 | 1): ProposalSection[] {
  const from = sections.findIndex((section) => section.id === id)
  if (from < 0) return [...sections]
  return moveItem(sections, from, from + direction)
}

export function preflightReady(items: readonly PreflightItem[]): boolean {
  return items.length > 0 && items.every((item) => item.done)
}

export function shareRatio(value: number, max: number): number {
  if (!Number.isFinite(value) || !Number.isFinite(max) || max <= 0) return 0
  return Math.max(0, Math.min(1, value / max))
}

export function formatHours(value: number, locale = "en-US"): string {
  return new Intl.NumberFormat(locale, { maximumFractionDigits: 1 }).format(value)
}

export function formatMoney(value: number, locale = "en-US", currency = "USD"): string {
  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    maximumFractionDigits: 0,
  }).format(value)
}

